import org.mockito.internal.matchers.*;
import org.mockito.internal.matchers.apachecommons.ReflectionEquals;
import org.mockito.internal.progress.HandyReturnValues;
import org.mockito.internal.progress.MockingProgress;
import org.mockito.internal.progress.ThreadSafeMockingProgress;
import static org.junit.Assert.*;

/**
 * Unit tests for org.mockito.Matchers.anyObject()
 */
public class Matchers_anyObject_TriageGen1Test {

    @Test
    public void testAnyObjectReturnsNull() {
        // Since the implementation calls reportMatcher(Any.ANY).returnNull(),
        // the expected behavior of anyObject() is to return null.
        // This test verifies the return type handling and the null return value.

        Object result = Matchers.anyObject();

        assertNull("anyObject() should return null as per its implementation", result);
    }

    @Test
    public void testAnyObjectWithSpecificType() {
        // Testing the generic <T> behavior by assigning to a specific type.
        // In Java, casting null to a specific type is valid.

        String result = Matchers.anyObject();

        assertNull("anyObject() should return null even when cast to String", result);
    }

    @Test
    public void testAnyObjectWithIntegerType() {
        // Testing the generic <T> behavior with a wrapper type.

        Integer result = Matchers.anyObject();

        assertNull("anyObject() should return null even when cast to Integer", result);
    }

    @Test
    public void testAnyObjectWithCustomClass() {
        // Testing the generic <T> behavior with a custom object type.

        class Dummy {}
        Dummy result = Matchers.anyObject();

        assertNull("anyObject() should return null even when cast to a custom class", result);
    }
}
